def deck_revealed_increasing(deck):
    n = len(deck)
    sorted_deck = sorted(deck)
    positions = list(range(n))                                             # remaining positions still needing a value assigned
    result = [0] * n
    reveal_next = True                                                     # True = reveal (assign) now; False = skip (move to back) now
    i = 0
    while positions:
        pos = positions.pop(0)                                             # O(n) shift to remove from the FRONT of a plain list
        if reveal_next:
            result[pos] = sorted_deck[i]
            i += 1
        else:
            positions.append(pos)                                         # put it back at the END, simulating the "skip" step
        if positions:
            reveal_next = not reveal_next
    return result


if __name__ == "__main__":
    print(deck_revealed_increasing([17, 13, 11, 2, 3, 5, 7]))

