import java.util.*;

public class Main {
    int[] deckRevealedIncreasing(int[] deck) {
        int n = deck.length;
        int[] sortedDeck = deck.clone();
        Arrays.sort(sortedDeck);
        List<Integer> positions = new ArrayList<>();
        for (int i = 0; i < n; i++) positions.add(i);                               // remaining positions still needing a value assigned
        int[] result = new int[n];
        boolean revealNext = true;                                                    // true = reveal (assign) now; false = skip (move to back) now
        int idx = 0;
        while (!positions.isEmpty()) {
            int pos = positions.remove(0);                                              // O(n) shift to remove from the FRONT of a plain list
            if (revealNext) {
                result[pos] = sortedDeck[idx++];
            } else {
                positions.add(pos);                                                       // put it back at the END, simulating the "skip" step
            }
            if (!positions.isEmpty()) revealNext = !revealNext;
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] deck = {17, 13, 11, 2, 3, 5, 7};
        System.out.println(Arrays.toString(solution.deckRevealedIncreasing(deck)));
    }
}

