using namespace std;

vector<int> deckRevealedIncreasing(vector<int>& deck) {
    int n = deck.size();
    vector<int> sortedDeck = deck;
    sort(sortedDeck.begin(), sortedDeck.end());
    vector<int> positions;
    for (int i = 0; i < n; i++) positions.push_back(i);                              // remaining positions still needing a value assigned
    vector<int> result(n);
    bool revealNext = true;                                                             // true = reveal (assign) now; false = skip (move to back) now
    int idx = 0;
    while (!positions.empty()) {
        int pos = positions.front();
        positions.erase(positions.begin());                                                // O(n) shift to remove from the FRONT of a plain vector
        if (revealNext) {
            result[pos] = sortedDeck[idx++];
        } else {
            positions.push_back(pos);                                                        // put it back at the END, simulating the "skip" step
        }
        if (!positions.empty()) revealNext = !revealNext;
    }
    return result;
}

int main() {
    vector<int> deck = {17, 13, 11, 2, 3, 5, 7};
    vector<int> result = deckRevealedIncreasing(deck);
