    int[] deckRevealedIncreasing(int[] deck) {
        int n = deck.length;
        int[] sortedDeck = deck.clone();
        Arrays.sort(sortedDeck);
        Deque<Integer> positions = new ArrayDeque<>();
        for (int i = 0; i < n; i++) positions.addLast(i);                            // positions still needing a value, in original order
        int[] result = new int[n];
        for (int val : sortedDeck) {                                                   // assign values in ASCENDING order, since they reveal in that order
            int pos = positions.pollFirst();                                             // this position gets the next (smallest remaining) value
            result[pos] = val;
            if (!positions.isEmpty()) {
                positions.addLast(positions.pollFirst());                                    // simulate the "move next card to the bottom" skip step
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] deck = {17, 13, 11, 2, 3, 5, 7};
        System.out.println(Arrays.toString(solution.deckRevealedIncreasing(deck)));
